private void assertAuthorization(Operation operation, ConfiguredObject<?> configuredObject, Operation aclOperation, ObjectType aclObjectType, ObjectProperties expectedProperties, ConfiguredObject... objects) {
    configureAccessPlugin(Result.ALLOWED);
    _securityManager.authorise(operation, configuredObject);
    verify(_accessControl).authorise(eq(aclOperation), eq(aclObjectType), eq(expectedProperties));
    configureAccessPlugin(Result.DENIED);
    try {
        _securityManager.authorise(operation, configuredObject);
        fail("AccessControlException is expected");
    } catch (AccessControlException e) {
        String expectedMessage = "Permission " + aclOperation.name() + " " + aclObjectType.name() + " is denied for : " + operation.name() + " " + configuredObject.getCategoryClass().getSimpleName() + " '" + configuredObject.getAttribute(ConfiguredObject.NAME) + "' on";
        assertTrue("Unexpected exception message: " + e.getMessage() + " vs " + expectedMessage, e.getMessage().startsWith(expectedMessage));
        for (ConfiguredObject object : objects) {
            String parentInfo = object.getCategoryClass().getSimpleName() + " '" + object.getAttribute(ConfiguredObject.NAME) + "'";
            assertTrue("Exception message does not contain information about parent object " + object.getCategoryClass() + " " + object.getAttribute(ConfiguredObject.NAME) + ":" + e.getMessage(), e.getMessage().contains(parentInfo));
        }
    }
    verify(_accessControl, times(2)).authorise(eq(aclOperation), eq(aclObjectType), eq(expectedProperties));
}

